questions.solutionCode:
function solve(leafStr, proofStr, rootStr) {
  let current = leafStr;
  const proof = JSON.parse(proofStr);
  for (const node of proof) {
    if (node.position === 'left') {
      current = node.hash + current;
    } else {
      current = current + node.hash;
    }
  }
  return current === rootStr ? 'true' : 'false';
}
